+
+		output := harnessWrite(t, val1)
+		val2 := harnessRead(t, output)
+
+		body2, _ := val2.GetMapKey("body")
+		p2, _ := body2.GetMapKey("p")
+		text2, _ := p2.StringValue()
+		if text2 != "<script>" {
+			t.Fatalf("round-trip changed text from '<script>' to '%s'", text2)
