+
+		textVal, err := target.GetMapKey("#text")
+		if err != nil {
+			t.Fatalf("round-trip lost text: %v", err)
+		}
+		textStr, _ := textVal.StringValue()
+		if textStr != "1 < 2 & 3 > 0" {
